#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    // Choose a chunk size that avoids too many blocks but still exposes parallelism.
    // You can tune this; correctness does not depend on it.
    const std::size_t blockSize = 1u << 14; // 16384
    const std::size_t numBlocks = (n + blockSize - 1) / blockSize;

    std::vector<double> blockSums(numBlocks, 0.0);   // sum of each block
    std::vector<double> blockOffsets(numBlocks, 0.0); // exclusive prefix of block sums

    // 1) Compute local prefix sums within each block and record each block's total.
    #pragma omp parallel for schedule(static)
    for (std::int64_t b = 0; b < static_cast<std::int64_t>(numBlocks); ++b) {
        const std::size_t begin = static_cast<std::size_t>(b) * blockSize;
        const std::size_t end   = (begin + blockSize < n) ? (begin + blockSize) : n;

        double run = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            run += x[i];
            output[i] = run;
        }
        blockSums[static_cast<std::size_t>(b)] = run;
    }

    // 2) Compute offsets (exclusive scan) of block sums.
    // This step is cheap (numBlocks elements). Keep it serial for simplicity and correctness.
    double offset = 0.0;
    for (std::size_t b = 0; b < numBlocks; ++b) {
        blockOffsets[b] = offset;
        offset += blockSums[b];
    }

    // 3) Add the block offset to every element in the block (except offset=0 for first block).
    #pragma omp parallel for schedule(static)
    for (std::int64_t b = 0; b < static_cast<std::int64_t>(numBlocks); ++b) {
        const std::size_t bb = static_cast<std::size_t>(b);
        const double add = blockOffsets[bb];
        if (add == 0.0) continue;

        const std::size_t begin = bb * blockSize;
        const std::size_t end   = (begin + blockSize < n) ? (begin + blockSize) : n;

        for (std::size_t i = begin; i < end; ++i) {
            output[i] += add;
        }
    }
}
